春对象 春;
梅花对象 梅花;
杏花对象 杏花;
public 春对象 描述春天() {
    梅花.状态=谢了;
    杏花.状态=开了;
    春.空气状态=暖气;
    春.梅花状态=谢了;
    春.杏花状态=开了;
    return 春;
}
``
